300:     /// A confirmação é obrigatória e mostra o valor: dar baixa por engano numa conta
301:     /// vencida apaga uma dívida real, e o erro só aparece no fim do mês.
302:     /// </summary>
303:     [RelayCommand]
304:     private async Task ReceberAsync(LinhaContaAtraso? conta)
305:     {
306:         if (conta is null) return;
307: 
308:         try
309:         {
310:             SessaoUsuario.Atual.Exigir(Permissao.EditarFinanceiro, "dar baixa em conta de paciente");
311: 
312:             if (!_dialogo.Confirmar(
313:                     "Receber conta",
314:                     $"Registrar o recebimento de {conta.Valor} ({conta.Descricao})?"))
315:                 return;
316: 
317:             using var scope = _escopos.CreateScope();

317:             using var scope = _escopos.CreateScope();
318:             var servico = scope.ServiceProvider.GetRequiredService<InadimplenciaService>();
319: 
320:             await servico.ReceberAsync(
321:                 conta.LancamentoId,
322:                 DateOnly.FromDateTime(DateTime.Today),
323:                 operador: SessaoUsuario.Atual.Operador);
324: 
325:             _snackbar.Sucesso("Recebimento registrado.");
326:             await CarregarAsync();
327:         }
328:         catch (Exception ex)
329:         {
330:             Clinica.Application.Diagnostico.Registrar("Financeiro — recebimento não pôde ser registrado", ex);
331:             Mensagem = ex.Message;
332:             MensagemEhErro = true;
333:         }
334:     }

